#include <map>
#include <string>

struct CaseCmp {
    bool ignore_case;
    CaseCmp(bool ic = false) : ignore_case(ic) {}
    bool operator()(const std::string& a, const std::string& b) const {
        if (ignore_case) {
            // Simplified case-insensitive comparison (requires custom function)
            // return tolower(a) < tolower(b);
            return a.length() < b.length(); // Placeholder for demonstration
        }
        return a < b;
    }
};

int main() {
    // Default case-sensitive comparison
    std::map<std::string, int, CaseCmp> sensitive_map;

    // Runtime configured case-insensitive comparison
    CaseCmp nocase_config(true);
    std::map<std::string, int, CaseCmp> insensitive_map(nocase_config);
}
